import { chromium } from 'playwright'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } })

const consoleErrors = []
page.on('console', (msg) => {
  if (msg.type() === 'error') consoleErrors.push(msg.text())
})
page.on('pageerror', (err) => consoleErrors.push(String(err)))

await page.goto('http://localhost:3311/', { waitUntil: 'networkidle' })
await page.screenshot({ path: '/tmp/pwtest/01-home.png' })

// Confirm ViewTransition API is in use (feature-detect on click)
const supportsVT = await page.evaluate(() => 'startViewTransition' in document)
console.log('Browser supports View Transitions API:', supportsVT)

// Click first product thumbnail and capture mid-transition + settled frames
const firstCard = page.locator('.product-card').first()
const firstCardName = await firstCard.locator('h2').innerText()
console.log('Clicking product:', firstCardName)

await firstCard.click()
// capture ASAP to try to catch mid-transition frame
await page.waitForTimeout(80)
await page.screenshot({ path: '/tmp/pwtest/02-mid-transition.png' })
await page.waitForLoadState('networkidle')
await page.waitForTimeout(500)
await page.screenshot({ path: '/tmp/pwtest/03-detail-settled.png' })

const url = page.url()
console.log('Navigated to:', url)

// Navigate back
const backLink = page.locator('.back-link')
await backLink.click()
await page.waitForTimeout(80)
await page.screenshot({ path: '/tmp/pwtest/04-mid-back.png' })
await page.waitForLoadState('networkidle')
await page.waitForTimeout(500)
await page.screenshot({ path: '/tmp/pwtest/05-home-settled.png' })

console.log('Console errors:', JSON.stringify(consoleErrors, null, 2))

await browser.close()

