import { chromium } from 'playwright'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } })

page.on('console', (msg) => console.log('[console]', msg.type(), msg.text()))
page.on('pageerror', (err) => console.log('[pageerror]', String(err)))
page.on('requestfailed', (req) => console.log('[requestfailed]', req.url(), req.failure()))
page.on('response', (res) => {
  if (res.status() >= 400) console.log('[response-error]', res.status(), res.url())
})

await page.goto('http://localhost:3311/', { waitUntil: 'networkidle' })

const href = await page.locator('.product-card').first().getAttribute('href')
console.log('href attr:', href)

await page.locator('.product-card').first().click()
await page.waitForTimeout(1000)
console.log('URL after click + 1s:', page.url())

await page.waitForTimeout(2000)
console.log('URL after click + 3s:', page.url())

await browser.close()

